Pure Valibot metadata
```ts
import * as env from '@okikio/env/valibot';
import * as v from 'valibot';

const Port = v.pipe(
  v.string(),
  v.title('HTTP port'),
  v.description('Port used by the service listener.'),
  v.examples(['8787']),
);
const ServiceEnvironment = env.define({ PORT: Port });
```

